<?php
namespace App\Controllers;use App\Core\Database;use App\Core\Security;use App\Core\Auth;
final class UserController{public function index():void{Auth::requireRole(['administrator']);$users=Database::connection()->query('SELECT id,name,email,role,status,created_at FROM users ORDER BY name')->fetchAll();$title='User Management';require BASE_PATH.'/app/Views/users/index.php';}public function create():void{Auth::requireRole(['administrator']);if($_SERVER['REQUEST_METHOD']==='POST'&&Security::validCsrf($_POST['_csrf']??null)){$s=Database::connection()->prepare('INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)');$s->execute([trim($_POST['name']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role']]);Security::flash('success','User account created.');Security::redirect('users');}$title='Add User';require BASE_PATH.'/app/Views/users/form.php';}public function delete():void{Auth::requireRole(['administrator']);if(!Security::validCsrf($_POST['_csrf']??null)){Security::flash('danger','Request expired.');Security::redirect('users');}$id=(int)$_POST['id'];if($id===(int)Auth::user()['id']){Security::flash('danger','You cannot delete your current account.');Security::redirect('users');}$db=Database::connection();foreach([['checkouts','user_id'],['stock_checks','checked_by'],['audit_logs','user_id']] as [$table,$column]){try{$s=$db->prepare("SELECT COUNT(*) FROM `$table` WHERE `$column`=?");$s->execute([$id]);if((int)$s->fetchColumn()>0){Security::flash('danger','This user cannot be deleted because activity history exists.');Security::redirect('users');}}catch(\PDOException $e){}}$db->prepare('DELETE FROM users WHERE id=?')->execute([$id]);Security::flash('success','User deleted.');Security::redirect('users');}}
